CREATE TABLE profiles (id text PRIMARY KEY, name text NOT NULL, timezone text NOT NULL, created_at text NOT NULL);
CREATE TABLE connections (id text PRIMARY KEY, profile_id text NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, provider_id text NOT NULL, institution_id text NOT NULL, status text NOT NULL CHECK(status IN ('active','expired','revoked','error')), created_at text NOT NULL, last_synced_at text, UNIQUE(profile_id,id));
CREATE TABLE consents (id text PRIMARY KEY, profile_id text NOT NULL, connection_id text NOT NULL, purpose text NOT NULL CHECK(purpose='account_information'), granted_at text NOT NULL, expires_at text NOT NULL, revoked_at text, provider text NOT NULL, FOREIGN KEY(profile_id,connection_id) REFERENCES connections(profile_id,id) ON DELETE CASCADE, UNIQUE(profile_id,connection_id));
CREATE TABLE accounts (id text PRIMARY KEY, profile_id text NOT NULL, connection_id text NOT NULL, provider_account_id text NOT NULL, name text NOT NULL, institution_name text NOT NULL, kind text NOT NULL CHECK(kind IN ('current','card','cash','savings')), balance_minor bigint NOT NULL, currency text NOT NULL CHECK(currency ~ '^[A-Z]{3}$'), balance_updated_at text NOT NULL, FOREIGN KEY(profile_id,connection_id) REFERENCES connections(profile_id,id) ON DELETE CASCADE, UNIQUE(profile_id,id), UNIQUE(profile_id,connection_id,id), UNIQUE(profile_id,connection_id,provider_account_id));
CREATE TABLE transactions (id text PRIMARY KEY, profile_id text NOT NULL, account_id text NOT NULL, connection_id text NOT NULL, provider_id text NOT NULL, provider_transaction_id text NOT NULL, revision integer NOT NULL CHECK(revision>0), source text NOT NULL CHECK(source IN ('bank','csv','manual')), status text NOT NULL CHECK(status IN ('pending','booked','reversed')), amount_minor bigint NOT NULL, currency text NOT NULL CHECK(currency ~ '^[A-Z]{3}$'), description text NOT NULL, merchant_name text, merchant_key text, booked_on date, authorized_on date, observed_at text NOT NULL, kind text NOT NULL CHECK(kind IN ('expense','income','transfer','card_settlement','refund','cash_withdrawal')), reference text, related_transaction_id text, related_account_id text, content_hash text NOT NULL, FOREIGN KEY(profile_id,connection_id,account_id) REFERENCES accounts(profile_id,connection_id,id) ON DELETE CASCADE, UNIQUE(profile_id,id), UNIQUE(profile_id,connection_id,id), UNIQUE(profile_id,connection_id,account_id,provider_id,provider_transaction_id), FOREIGN KEY(profile_id,connection_id,related_account_id) REFERENCES accounts(profile_id,connection_id,id) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY(profile_id,connection_id,related_transaction_id) REFERENCES transactions(profile_id,connection_id,id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE source_observations (id text PRIMARY KEY, profile_id text NOT NULL, connection_id text NOT NULL, account_id text NOT NULL, provider_id text NOT NULL, provider_record_id text NOT NULL, status text NOT NULL, content_hash text NOT NULL, observed_at text NOT NULL, payload jsonb NOT NULL, FOREIGN KEY(profile_id,connection_id,account_id) REFERENCES accounts(profile_id,connection_id,id) ON DELETE CASCADE, UNIQUE(profile_id,connection_id,account_id,provider_id,provider_record_id,status,content_hash));
CREATE TABLE classification_feedback (profile_id text NOT NULL, transaction_id text NOT NULL, category_id text NOT NULL, scope text NOT NULL CHECK(scope IN ('once','merchant')), created_at text NOT NULL, PRIMARY KEY(profile_id,transaction_id), FOREIGN KEY(profile_id,transaction_id) REFERENCES transactions(profile_id,id) ON DELETE CASCADE);
CREATE TABLE preferences (profile_id text NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, merchant_key text NOT NULL, category_id text NOT NULL, PRIMARY KEY(profile_id,merchant_key));
CREATE TABLE match_decisions (profile_id text NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, match_id text NOT NULL, state text NOT NULL CHECK(state IN ('confirmed','rejected','undone')), decided_at text NOT NULL, PRIMARY KEY(profile_id,match_id));
CREATE TABLE sync_runs (id text PRIMARY KEY, profile_id text NOT NULL, connection_id text NOT NULL, inserted integer NOT NULL CHECK(inserted>=0), updated integer NOT NULL CHECK(updated>=0), unchanged integer NOT NULL CHECK(unchanged>=0), rejected integer NOT NULL CHECK(rejected>=0), synced_at text NOT NULL, FOREIGN KEY(profile_id,connection_id) REFERENCES connections(profile_id,id) ON DELETE CASCADE);
CREATE INDEX transactions_profile_order ON transactions(profile_id,id);
CREATE INDEX observations_profile ON source_observations(profile_id);
